dren: [Text('EGP ${p['price']}', style: const TextStyle(color: NovaColors.red, fontWeight: FontWeight.w900)), const SizedBox(width: 10), Text('Stock ${p['stock_qty']}', style: const TextStyle(fontSize: 10, color: NovaColors.muted)), const Spacer(), NovaStatusPill(p['is_active'] == true ? 'active' : 'archived')])])), PopupMenuButton<String>(onSelected: (v) { if (v == 'edit') _edit(p); if (v == 'archive') _archive(p); }, itemBuilder: (_) => const [PopupMenuItem(value: 'edit', child: Text('Edit product')), PopupMenuItem(value: 'archive', child: Text('Archive'))])])), if (total > 30) Row(mainAxisAlignment: MainAxisAlignment.center, children: [IconButton(onPressed: page > 1 ? () { page--; _load(); } : null, icon: const Icon(Icons.chevron_left)), Text('$page / ${(total / 30).ceil()}'), IconButton(onPressed: page * 30 < total ? () { page++; _load(); } : null, icon: const Icon(Icons.chevron_right))]) ])); }
