class _ProductEditorDialog extends StatefulWidget { const _ProductEditorDialog({this.product}); final Map<String, dynamic>? product; @override State<_ProductEditorDialog> createState() => _ProductEditorDialogState(); }
class _ProductEditorDialogState extends State<_ProductEditorDialog> {
  final form = GlobalKey<FormState>(); late final sku = TextEditingController(text: '${widget.product?['sku'] ?? ''}'); late final slug = TextEditingController(text: '${widget.product?['slug'] ?? ''}'); late final name = TextEditingController(text: '${widget.product?['name'] ?? ''}'); late final category = TextEditingController(text: '${widget.product?['category'] ?? ''}'); late final description = TextEditingController(text: '${widget.product?['description'] ?? ''}'); late final price = TextEditingController(text: '${widget.product?['price'] ?? ''}'); late final stock = TextEditingController(text: '${widget.product?['stock_qty'] ?? 0}'); File? image; bool busy = false; bool featured = false; bool active = true;
  @override void initState() { super.initState(); featured = widget.product?['featured'] == true; active = widget.product?['is_active'] != false; }
