    final body = {'sku': sku.text.trim(), 'slug': slug.text.trim(), 'name': name.text.trim(), 'category': category.text.trim(), 'description': description.text.trim(), 'price': price.text.trim(), 'stock_qty': int.tryParse(stock.text) ?? 0, 'image_url': imageUrl, 'featured': featured, 'is_active': active};
    if (widget.product == null) { await api.post('/admin/products', data: body); } else { await api.patch('/admin/products/${widget.product!['id']}', data: body); }
    if (mounted) Navigator.pop(context, true);
  } catch (e) { if (mounted) ScaffoldMessenger.of(context).showSnackBar(SnackBar(content: Text('$e'))); } finally { if (mounted) setState(() => busy = false); } }
