  Widget _field(TextEditingController c, String label, {bool number = false, bool required = true, int maxLines = 1}) => Padding(padding: const EdgeInsets.only(bottom: 10), child: TextFormField(controller: c, maxLines: maxLines, keyboardType: number ? const TextInputType.numberWithOptions(decimal: true) : TextInputType.text, decoration: InputDecoration(labelText: label), validator: required ? (v) => (v == null || v.trim().isEmpty) ? 'Required' : (number && double.tryParse(v) == null) ? 'Enter a valid number' : null : null));
}
